import React, { useState, useEffect } from 'react';
import CoinflipGameCard from '../components/CoinflipGameCard';
import CreateCoinflipModal from '../components/CreateCoinflipModal';
import { useAuth } from '../context/AuthContext';

const CoinflipPage = ({ socket, setBalance }) => {
  const { user } = useAuth();
  const [coinflips, setCoinflips] = useState([]);
  const [activeCount, setActiveCount] = useState(0);
  const [totalInGames, setTotalInGames] = useState(0);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [sortBy, setSortBy] = useState('newest');
  const [loading, setLoading] = useState(true);

  // Fetch coinflips
  useEffect(() => {
    const fetchCoinflips = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip`);
        const data = await response.json();

        setCoinflips(data.coinflips);
        setActiveCount(data.activeCount);
        setTotalInGames(data.totalInGames); 
        setLoading(false);
      } catch (error) {
        console.error('Error fetching coinflips:', error);
        setLoading(false);
      }
    };

    fetchCoinflips();

    // Listen for new coinflips
    if (socket) {
      socket.on('newCoinflip', (data) => {
        setCoinflips(prev => [data, ...prev]);
        setActiveCount(prev => prev + 1);
        setTotalInGames(prev => prev + data.totalValue);
      });

      socket.on('coinflipJoined', (data) => {
        setCoinflips(prev => 
          prev.map(cf => cf.id === data.id ? data : cf)
        );
      });

      socket.on('coinflipResult', (data) => {
        setCoinflips(prev => 
          prev.map(cf => cf.id === data.id ? data : cf)
        );
      });
    }

    return () => {
      if (socket) {
        socket.off('newCoinflip');
        socket.off('coinflipJoined');
        socket.off('coinflipResult');
      }
    };
  }, [socket]);

  // Handle sort change
  const handleSortChange = (newSort) => {
    setSortBy(newSort);
    // In a real app, we would fetch sorted data from the server
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading coinflips...</p>
      </div>
    );
  }

  return (
    <div className="coinflip-page">
      <div className="page-header">
        <h1>Coinflip</h1>
        <div className="page-stats">
          <span>{activeCount} Active Games</span>
          <span>{totalInGames.toLocaleString()} AMP in Games</span>
        </div>
        <div className="page-actions">
          <select 
            value={sortBy} 
            onChange={(e) => handleSortChange(e.target.value)}
            className="sort-select"
          >
            <option value="newest">Newest</option>
            <option value="oldest">Oldest</option>
            <option value="value_high">Value High to Low</option>
            <option value="value_low">Value Low to High</option>
          </select>
          <button 
            className="btn btn-primary" 
            onClick={() => setShowCreateModal(true)}
          >
            BET ITEMS
          </button>
          <button className="btn btn-secondary">HISTORY</button>
        </div>
      </div>

      <div className="coinflip-list">
        {coinflips.length === 0 ? (
          <div className="empty-state">
            <p>No active coinflips. Create one to get started!</p>
          </div>
        ) : (
          coinflips.map(coinflip => (
            <CoinflipGameCard 
              key={coinflip.id} 
              coinflip={coinflip} 
              userId={user?.id}
              socket={socket}
            />
          ))
        )}
      </div>

      {showCreateModal && (
        <CreateCoinflipModal 
          onClose={() => setShowCreateModal(false)} 
          userId={user?.id}
          socket={socket}
          setBalance={setBalance}
        />
      )}
    </div>
  );
};

export default CoinflipPage;
